from fractions import Fraction
def canary_gate(control,canary,min_events,max_excess):
    # Own fixed eligible counts:(bad,total),same observation window/population definition.
    for row in (control,canary):
        if type(row) is not tuple or len(row)!=2 or any(type(x) is not int for x in row) or not 0<=row[0]<=row[1]<=1000000:raise ValueError('invalid canary counts')
    if type(min_events) is not int or not 1<=min_events<=1000000 or type(max_excess) is not Fraction or not 0<=max_excess<=1:raise ValueError('invalid canary policy')
    if min(control[1],canary[1])<min_events:return 'hold-insufficient-evidence'
    difference=Fraction(canary[0],canary[1])-Fraction(control[0],control[1])
    return 'stop-investigate' if difference>max_excess else 'eligible-for-next-reviewed-step'

def rollback_compatibility(artifact,database_schema):
    # Toy explicit read ANDwrite schema support,not a migration/restore implementation.
    if type(artifact) is not tuple or len(artifact)!=3:raise ValueError('invalid artifact compatibility record')
    version,readable,writable=artifact
    if type(version) is not str or version not in ('v1','bridge','v2'):raise ValueError('unknown artifact')
    if any(type(values) is not frozenset or not values or any(type(x) is not int or x not in (1,2) for x in values) for values in (readable,writable)):raise ValueError('invalid schema support')
    if type(database_schema) is not int or database_schema not in (1,2):raise ValueError('unknown database schema')
    return database_schema in readable and database_schema in writable

print(canary_gate((1,1000),(10,1000),100,Fraction(1,200)))
print(canary_gate((1,1000),(0,10),100,Fraction(1,200)))
print(canary_gate((1,1000),(2,1000),100,Fraction(1,200)))
print(rollback_compatibility(('v1',frozenset({1}),frozenset({1})),2))
print(rollback_compatibility(('bridge',frozenset({1,2}),frozenset({1,2})),2))
